#!/usr/bin/env python3
"""Generate Android's execution mirror from the shared native-model manifest."""
import argparse
import json
from pathlib import Path

MOBILE = Path(__file__).resolve().parents[1]
MANIFEST = MOBILE / "android-model-runtime.json"
OUTPUT = MOBILE / "exact-package" / "android" / "NativeModelCatalog.kt"


def quote(value: str) -> str:
    return json.dumps(value, ensure_ascii=False)


def generate() -> str:
    models = json.loads(MANIFEST.read_text(encoding="utf-8"))["models"]
    lines = [
        "// Generated by mobile/scripts/gen_android_model_catalog.py from mobile/android-model-runtime.json.",
        "// Shared TypeScript owns selection, consent and prompts; this is the native execution mirror only.",
        "package choir.autoradio",
        "",
        "enum class NativeModelKind { TEXT, EMBEDDING, VAD, TTS }",
        "",
        "data class NativeModelFile(val name: String, val url: String, val sha256: String, val bytes: Long)",
        "",
        "data class NativeModelSpec(",
        "    val id: String,",
        "    val kind: NativeModelKind,",
        "    val files: List<NativeModelFile>,",
        "    val embeddingDimension: Int = 0,",
        "    val supportedVoices: List<String> = emptyList(),",
        ") {",
        "    val bytes: Long get() = files.sumOf { it.bytes }",
        "}",
        "",
        "object NativeModelCatalog {",
        "    val models: List<NativeModelSpec> = listOf(",
    ]
    for model in models:
        lines.extend([
            "        NativeModelSpec(",
            f"            id = {quote(model['id'])},",
            f"            kind = NativeModelKind.{model['kind'].upper()},",
            "            files = listOf(",
        ])
        for file in model["files"]:
            lines.append(
                "                NativeModelFile("
                f"name = {quote(file['name'])}, url = {quote(file['url'])}, "
                f"sha256 = {quote(file['sha256'])}, bytes = {file['bytes']}L),"
            )
        lines.extend([
            "            ),",
            f"            embeddingDimension = {model['embeddingDimension']},",
            "            supportedVoices = listOf(" + ", ".join(quote(v) for v in model["supportedVoices"]) + "),",
            "        ),",
        ])
    lines.extend([
        "    )",
        "",
        "    fun require(id: String): NativeModelSpec {",
        "        if (id.isEmpty() || id.any { it !in 'a'..'z' && it !in 'A'..'Z' && it !in '0'..'9' && it !in \"-._:\" }) {",
        "            throw IllegalArgumentException(\"invalid native model id\")",
        "        }",
        "        return models.singleOrNull { it.id == id } ?: throw IllegalArgumentException(\"unknown native model id\")",
        "    }",
        "}",
        "",
    ])
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="refuse a stale generated file without writing it")
    args = parser.parse_args()
    text = generate()
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text(encoding="utf-8") != text:
            raise SystemExit(f"stale {OUTPUT}; run {Path(__file__).name}")
        print(f"native model catalog matches {MANIFEST}")
        return
    OUTPUT.write_text(text, encoding="utf-8")
    print(f"wrote {OUTPUT}")


if __name__ == "__main__":
    main()
